package org.transittr.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;
/** Actual settings-button clicks, persistence and dark native/widget rendering on API 8+. */
public final class ThemeCheck extends Instrumentation {
 private Activity activity;private ClassLoader loader;private boolean original;
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private void screen(final int screen){runOnMainSync(new Runnable(){public void run(){try{Field f=activity.getClass().getDeclaredField("screen");f.setAccessible(true);f.setInt(activity,screen);Method build=activity.getClass().getDeclaredMethod("build");build.setAccessible(true);build.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();}
 private boolean dark(){return getTargetContext().getSharedPreferences("appearance-v1",0).getBoolean("dark",false);}
 private void status(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(1,b);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();boolean passed=false;try{original=dark();String favorites=getTargetContext().getSharedPreferences("widget-favorites-v1",0).getString("entries","[]");activity=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));loader=activity.getClassLoader();screen(2);runOnMainSync(new Runnable(){public void run(){activity.findViewById(7602).performClick();}});waitForIdleSync();check(dark(),"dark preference saved by actual settings button");check(((Boolean)field(field(activity,"palette"),"dark")).booleanValue(),"settings uses dark palette");status("CAPTURE=THEME_DARK_SETTINGS");Thread.sleep(6000);
  screen(0);check(((Boolean)field(field(activity,"map"),"dark")).booleanValue(),"same OSM tiles rendered in dark mode");Thread.sleep(2000);status("CAPTURE=THEME_DARK_MAP");Thread.sleep(6000);screen(3);Thread.sleep(1200);check(((Boolean)field(field(field(activity,"catalog"),"palette"),"dark")).booleanValue(),"catalogue uses dark palette");status("CAPTURE=THEME_DARK_CATALOG");Thread.sleep(6000);
  final Class<?> widget=loader.loadClass("org.transittr.TransitWidget");final RemoteViews darkWidget=(RemoteViews)widget.getMethod("views",Context.class,Integer.TYPE).invoke(null,activity,-1);runOnMainSync(new Runnable(){public void run(){FrameLayout preview=new FrameLayout(activity);preview.setBackgroundColor(0xff111511);preview.setPadding(16,16,16,16);View content=darkWidget.apply(activity,preview);preview.addView(content,new FrameLayout.LayoutParams(-1,(int)(200*activity.getResources().getDisplayMetrics().density)));activity.setContentView(preview);}});status("CAPTURE=THEME_DARK_WIDGET");Thread.sleep(6000);
  final Activity editor=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.WidgetSetupActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(((Boolean)field(field(editor,"palette"),"dark")).booleanValue(),"favourites editor uses dark palette");status("CAPTURE=THEME_DARK_EDITOR");Thread.sleep(6000);runOnMainSync(new Runnable(){public void run(){editor.finish();activity.finish();}});activity=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();check(((Boolean)field(field(activity,"palette"),"dark")).booleanValue(),"dark theme persists after activity restart");screen(2);runOnMainSync(new Runnable(){public void run(){activity.findViewById(7601).performClick();}});waitForIdleSync();check(!dark(),"light preference saved by settings button");status("CAPTURE=THEME_LIGHT_SETTINGS");Thread.sleep(6000);check(favorites.equals(getTargetContext().getSharedPreferences("widget-favorites-v1",0).getString("entries","[]")),"theme changes preserve user favourites");passed=true;result.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; THEME_LIGHT_DARK=true; PERSISTENCE=true; MAP_CATALOG_WIDGET_EDITOR=true; FAVORITES_PRESERVED=true\n");
 }catch(Throwable e){java.io.StringWriter out=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(out));result.putString("stream","FAIL Android "+Build.VERSION.RELEASE+"\n"+out);}finally{getTargetContext().getSharedPreferences("appearance-v1",0).edit().putBoolean("dark",original).commit();try{if(activity!=null){screen(0);loader.loadClass("org.transittr.TransitWidget").getMethod("renderAll",Context.class).invoke(null,activity);}}catch(Exception ignored){}}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
